    @Override
    public boolean equals(Object o) {
        if (o == null) return false;
        return this.hashCode() == o.hashCode();
    }

    @Override
    public int hashCode() {
        String str = "";
        str += bT26.hashCode();
        str += aS27.hashCode();
        str += bTGrp27.hashCode();
        str += aTGrp27.hashCode();
        str += work.hashCode();
        str += bSGrp26.hashCode();
        str += bS27.hashCode();
        str += aT26.hashCode();
       return str.hashCode();
    }

